import{_ as a,o as s,c as e,a3 as o}from"./chunks/framework.CVt6dz2a.js";const u=JSON.parse('{"title":"EP.13 后处理管线与帧率保卫战","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.13-post-processing.md","filePath":"comics/EP.13-post-processing.md","lastUpdated":1793881879000}'),r={name:"comics/EP.13-post-processing.md"};function l(d,t,i,n,c,h){return s(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="ep-13-后处理管线与帧率保卫战" tabindex="-1">EP.13 后处理管线与帧率保卫战 <a class="header-anchor" href="#ep-13-后处理管线与帧率保卫战" aria-label="Permalink to &quot;EP.13 后处理管线与帧率保卫战&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/13-postprocessing/basics">13.1 基础入门：渲染目标与第一个 Bloom</a> 延伸阅读：<a href="./../guide/13-postprocessing/advanced">进阶篇</a> · <a href="./../guide/13-postprocessing/practice">实战篇</a> 动手演示：<a href="./../public/demos/postprocessing/first-bloom.html">first-bloom 第一个泛光</a> · <a href="./../public/demos/postprocessing/pass-order-lab.html">pass-order-lab Pass 顺序实验室</a> · <a href="./../public/demos/postprocessing/product-showcase.html">product-showcase 产品级画面合成</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱给场景一口气叠了 SSAO、Bloom、Film、Glitch、Bokeh 五个 Pass，帧率从 60 掉到 20，画面是华丽了，页面却卡成幻灯片。</td></tr><tr><td>② 揭秘</td><td>码叔画出 Pass 流水线：链上每一环都是&quot;读上一环的图 → 全屏加工 → 写给下一环&quot;，5 个效果 Pass 就是每帧 5 次以上的全屏绘制；省钱靠半分辨率与合并。</td></tr><tr><td>③ 实证</td><td>像素酱把 SSAO 换成烘焙 AO 贴图，把 Film 与暗角合并进一个自定义 ShaderPass，链从 5 环瘦到 2 环，帧率回到 60。</td></tr><tr><td>④ 结案</td><td>坑点清单：threshold 太低满屏泛光、resize 漏了 composer.setSize、OutputPass 没放链尾。码叔总结：先问要不要，再问放哪环——帧率是预算。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-每个-pass-≈-至少一次全屏绘制" tabindex="-1">① 每个 Pass ≈ 至少一次全屏绘制 <a class="header-anchor" href="#_1-每个-pass-≈-至少一次全屏绘制" aria-label="Permalink to &quot;① 每个 Pass ≈ 至少一次全屏绘制&quot;">​</a></h3><p>后处理链不是&quot;声明一堆效果&quot;，而是一条每帧执行的全屏流水线。帧预算可以粗算：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帧开销 ≈ 场景绘制 × 1 + Σ(每个 Pass 的全屏绘制 × 其内部趟数)</span></span></code></pre></div><p>UnrealBloomPass 内部是半分辨率 5 级模糊（10+ 趟，但分辨率递减）；SSAOPass 还要额外生成法线/深度缓冲，是最贵的一档。叠 5 个效果 Pass，中端设备很容易跌破 30fps。</p><h3 id="_2-省钱两招-半分辨率与合并" tabindex="-1">② 省钱两招：半分辨率与合并 <a class="header-anchor" href="#_2-省钱两招-半分辨率与合并" aria-label="Permalink to &quot;② 省钱两招：半分辨率与合并&quot;">​</a></h3><ul><li><strong>半分辨率</strong>：模糊类效果（Bloom、雾、辉光）对分辨率不敏感，在半分辨率甚至四分之一分辨率工作，肉眼几乎无差；</li><li><strong>合并</strong>：暗角、噪点、色调分离、饱和度这类&quot;单次采样、逐像素变换&quot;的小效果，可以合进<strong>同一个自定义 ShaderPass</strong>，一次全屏绘制做 N 件事。</li></ul><h3 id="_3-砍并实战" tabindex="-1">③ 砍并实战 <a class="header-anchor" href="#_3-砍并实战" aria-label="Permalink to &quot;③ 砍并实战&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原方案</th><th>优化后</th><th>省下的开销</th></tr></thead><tbody><tr><td>SSAOPass</td><td>烘焙 AO 贴图到模型 uv2</td><td>最大的一档直接归零</td></tr><tr><td>FilmPass + 暗角 ShaderPass</td><td>合并为一个 ShaderPass</td><td>省一次全屏绘制</td></tr><tr><td>GlitchPass 常驻</td><td>事件触发时才 enabled</td><td>常驻开销归零</td></tr></tbody></table><p>优化后链路：<code>RenderPass → UnrealBloomPass → StylePass(噪点+暗角) → OutputPass</code>，画面观感几乎不变，帧率 20 → 60。</p><h3 id="_4-顺序与收尾的纪律" tabindex="-1">④ 顺序与收尾的纪律 <a class="header-anchor" href="#_4-顺序与收尾的纪律" aria-label="Permalink to &quot;④ 顺序与收尾的纪律&quot;">​</a></h3><ul><li><code>RenderPass</code> 永远第一，<code>OutputPass</code> 永远最后且只加一个；</li><li>效果之间的顺序用一句话判断：<strong>&quot;这个效果应不应该看到那个效果的结果？&quot;</strong>（Bloom 在 Afterimage 前，拖尾就带辉光）；</li><li>临时关效果用 <code>pass.enabled = false</code>，不要反复增删 Pass。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：threshold 太低会怎样？</strong> 画面中大部分区域都超过阈值参与泛光，结果满屏糊成一片、亮度爆炸。抬高阈值，只让真正的发光体起辉。</li><li><strong>Q：resize 后辉光/暗角错位？</strong> 只调了 <code>renderer.setSize</code>，忘了 <code>composer.setSize</code>——渲染目标还是旧尺寸。两个都要调，相机也不要漏。</li><li><strong>Q：接上 composer 后颜色发灰/发暗？</strong> 九成是 OutputPass 缺失或没放链尾：色调映射与 sRGB 转换没人做了。</li><li><strong>Q：走 composer 后抗锯齿失效？</strong> <code>antialias:true</code> 只对直接上屏有效；渲染目标需要在 WebGL2 下用 <code>{ samples: 4 }</code> 的 WebGLRenderTarget 构造 composer，或链尾加 SMAAPass。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么说&quot;每个 Pass 至少一次全屏绘制&quot;？它对帧预算意味着什么？</li><li>Bloom 放在 Afterimage 之前与之后，视觉效果有什么差别？</li><li>一条链是 <code>RenderPass → Bloom → OutputPass</code>，你想加噪点和暗角，性能最优的做法是什么？</li></ol><details><summary>答案</summary><ol><li>每个 Pass 都要把上一环输出的整张纹理逐像素读入、加工、写出，这是一次覆盖全屏的片元计算。意味着 Pass 数量直接线性吃掉帧时间，移动端每环都要掂量。</li><li>Bloom 在前：Afterimage 混合的是&quot;已泛光&quot;的画面，拖尾带辉光，更梦幻；Afterimage 在前：Bloom 只对当前帧最亮处起辉，拖尾不发光，更干净可控。</li><li>把噪点和暗角合并进<strong>一个自定义 ShaderPass</strong>（一次全屏绘制做两件事），放在 Bloom 之后、OutputPass 之前；比挂两个独立 Pass 省一次全屏绘制。</li></ol></details>',21)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
